/**
 * Task 23: the CI deployment (generated by scripts/ci-config.mjs) shares the account with
 * production, so it must use only its own resources, and only it may run email log mode.
 * Its configs are generated at deploy time from the environment (git-ignored), so these tests
 * generate them from the committed templates with stand-in account values.
 */
import { describe, expect, it } from "vitest";
// @ts-expect-error -- Vite `?raw` imports (the files' text)
import prodRaw from "../wrangler.jsonc?raw";
// @ts-expect-error -- Vite `?raw` import
import prevRaw from "../wrangler.preview.jsonc?raw";
// @ts-expect-error -- Vite `?raw` import
import runnerRaw from "../wrangler.runner.jsonc?raw";
// @ts-expect-error -- plain JS module outside the package (the generator's pure core)
import { buildFromSources, ciNames, ciSettings, deploymentNames, parseJsonc, render } from "../../../scripts/ci-config-core.mjs";
import { STEPS_QUEUE, queueBaseName } from "../src/app.js";
import { emailLogAllowed } from "../src/services/email.js";
import type { Env } from "../src/env.js";
import { ARTIFACT_EVENTS_QUEUE } from "../src/services/artifact-events.js";
import { OUTBOX_DLQ, OUTBOX_QUEUE } from "../src/services/outbox-consumer.js";

/** whole-line comments only (as test/config.test.ts); the generated files have no inline ones */
const parse = (t: string) => JSON.parse(t.split("\n").filter((l) => !/^\s*\/\//.test(l)).join("\n"));

type Cfg = {
  name: string;
  vars: Record<string, string>;
  d1_databases?: Array<{ database_name: string; database_id: string }>;
  r2_buckets?: Array<{ bucket_name: string }>;
  limits?: { cpu_ms?: number };
  artifacts?: Array<{ namespace: string }>;
  services?: Array<{ service: string }>;
  queues: { producers?: Array<{ queue: string }>; consumers: Array<{ queue: string; dead_letter_queue?: string }> };
};
const prod = parse(prodRaw as string) as Cfg;
/** stand-ins for the account values scripts/deploy-ci.sh reads from apps/worker/.dev.vars */
const ENV = { COMMONFORGE_LIVE_BASE: "acct.workers.dev", COMMONFORGE_CI_D1_DATABASE_ID: "11111111-1111-4111-8111-111111111111", COMMONFORGE_EMAIL_FROM: "login@mail.example.org", COMMONFORGE_D1_DATABASE_ID: "22222222-2222-4222-8222-222222222222" };
const BASE = ENV.COMMONFORGE_LIVE_BASE;
const fresh = () => ({ worker: parseJsonc(prodRaw as string), preview: parseJsonc(prevRaw as string), runner: parseJsonc(runnerRaw as string) });
/** what scripts/ci-config.mjs writes for these settings */
function generate(env: Record<string, string> = ENV) {
  const s = ciSettings(env);
  const p = fresh();
  p.worker.d1_databases[0].database_id = s.prodD1Id;
  return render(buildFromSources(p, s.base, ciNames(s.base, s.d1Id), { adminEmails: "@commonforge.invalid", emailFrom: s.emailFrom })) as Record<string, string>;
}
const files = generate();
const ci = parse(files["wrangler.deploy-ci.jsonc"]!) as Cfg;
const ciRunner = parse(files["wrangler.deploy-ci-runner.jsonc"]!) as Cfg;
const ciPreview = parse(files["wrangler.deploy-ci-preview.jsonc"]!) as Cfg;

describe("CI deployment config", () => {
  it("production keeps send mode; only CI logs sign-in links", () => {
    expect(prod.name).toBe("commonforge-worker");
    expect(prod.vars.COMMONFORGE_EMAIL_MODE).toBe("send");
    expect(ci.name).toBe("commonforge-ci-worker");
    expect(ci.vars.COMMONFORGE_EMAIL_MODE).toBe("log");
  });

  it("every CI resource is its own", () => {
    expect(ci.d1_databases![0]!.database_id).not.toBe(prod.d1_databases![0]!.database_id);
    expect(ci.d1_databases![0]!.database_name).toBe("commonforge-ci");
    expect(ci.r2_buckets![0]!.bucket_name).toBe("commonforge-assets-ci");
    expect(ciPreview.r2_buckets![0]!.bucket_name).toBe("commonforge-assets-ci");
    expect(ci.artifacts![0]!.namespace).toBe("commonforge-ci");
    // folders and uploads: the presign bucket var names the bucket the binding points at, and the hash step gets its CPU
    expect(ci.vars.COMMONFORGE_ASSETS_BUCKET).toBe(ci.r2_buckets![0]!.bucket_name);
    expect(prod.vars.COMMONFORGE_ASSETS_BUCKET).toBe(prod.r2_buckets![0]!.bucket_name);
    expect(prod.limits?.cpu_ms).toBe(300000);
    expect(ci.limits?.cpu_ms).toBe(300000);
    expect(ci.vars.COMMONFORGE_NAMESPACE_PREFIX).toBe("commonforge-ci");
    expect(ci.vars.COMMONFORGE_DEPLOY_WORKER_PREFIX).toBe("cfci");
    expect(ciRunner.vars.COMMONFORGE_DEPLOY_WORKER_PREFIX).toBe("cfci");
    expect(ciRunner.services).toEqual([{ binding: "CONTROL", service: "commonforge-ci-worker" }]);
    const prodQueues = new Set([...prod.queues.producers!.map((p) => p.queue), ...prod.queues.consumers.map((c) => c.queue)]);
    const ciQueues = [...ci.queues.producers!.map((p) => p.queue), ...ci.queues.consumers.flatMap((c) => [c.queue, c.dead_letter_queue ?? c.queue]), ...ciRunner.queues.consumers.map((c) => c.queue)];
    for (const qn of ciQueues) {
      expect(prodQueues.has(qn)).toBe(false);
      expect(qn.endsWith(ci.vars.COMMONFORGE_QUEUE_SUFFIX!)).toBe(true);
    }
  });

  it("the CI queues dispatch to the same consumers", () => {
    const suffix = ci.vars.COMMONFORGE_QUEUE_SUFFIX;
    const known = [STEPS_QUEUE, OUTBOX_QUEUE, OUTBOX_DLQ, ARTIFACT_EVENTS_QUEUE].sort();
    expect(ci.queues.consumers.map((c) => queueBaseName(c.queue, suffix)).sort()).toEqual(known);
    // production has no suffix: names pass unchanged
    expect(prod.queues.consumers.map((c) => queueBaseName(c.queue, prod.vars.COMMONFORGE_QUEUE_SUFFIX)).sort()).toEqual(known);
    expect(queueBaseName("-ci", "-ci")).toBe("-ci");
  });

  it("review m2: the generated CI configs carry the account values given, and nothing is committed", () => {
    expect(Object.keys(files).sort()).toEqual(["wrangler.deploy-ci-preview.jsonc", "wrangler.deploy-ci-runner.jsonc", "wrangler.deploy-ci.jsonc"]);
    expect(ci.vars.COMMONFORGE_DEPLOYMENT).toBe("ci");
    expect(prod.vars.COMMONFORGE_DEPLOYMENT).toBeUndefined();
    expect(ci.d1_databases![0]!.database_id).toBe(ENV.COMMONFORGE_CI_D1_DATABASE_ID);
    expect(ci.vars.COMMONFORGE_APP_URL).toBe(`https://commonforge-ci-worker.${BASE}`);
    expect(ci.vars.COMMONFORGE_PREVIEW_URL).toBe(`https://commonforge-ci-preview.${BASE}`);
    expect(ciRunner.vars.COMMONFORGE_WORKER_URL).toBe(`https://commonforge-ci-worker.${BASE}`);
    expect(ci.vars.COMMONFORGE_EMAIL_FROM).toBe(ENV.COMMONFORGE_EMAIL_FROM);
    expect((ci as unknown as { send_email: Array<{ allowed_sender_addresses: string[] }> }).send_email[0]!.allowed_sender_addresses).toEqual([ENV.COMMONFORGE_EMAIL_FROM]);
    // deterministic: the same inputs give the same text
    expect(generate()).toEqual(files);
  });

  it("refuses missing, malformed or placeholder account values, and production's D1 id", () => {
    for (const k of Object.keys(ENV)) expect(() => generate({ ...ENV, [k]: "" })).toThrow(new RegExp(k));
    expect(() => generate({ ...ENV, COMMONFORGE_CI_D1_DATABASE_ID: prod.d1_databases![0]!.database_id })).toThrow(/COMMONFORGE_CI_D1_DATABASE_ID/);
    expect(() => generate({ ...ENV, COMMONFORGE_CI_D1_DATABASE_ID: "commonforge-ci" })).toThrow(/COMMONFORGE_CI_D1_DATABASE_ID/);
    expect(() => generate({ ...ENV, COMMONFORGE_EMAIL_FROM: prod.vars.COMMONFORGE_EMAIL_FROM! })).toThrow(/COMMONFORGE_EMAIL_FROM/);
    expect(() => generate({ ...ENV, COMMONFORGE_LIVE_BASE: "https://acct.workers.dev" })).toThrow(/COMMONFORGE_LIVE_BASE/);
    // review M1: production's id is required, so CI's can never silently be production's
    expect(() => generate({ ...ENV, COMMONFORGE_D1_DATABASE_ID: ENV.COMMONFORGE_CI_D1_DATABASE_ID })).toThrow(/production's database/);
    expect(() => generate({ ...ENV, COMMONFORGE_D1_DATABASE_ID: ENV.COMMONFORGE_CI_D1_DATABASE_ID.toUpperCase() })).toThrow(/production's database/);
    const { COMMONFORGE_D1_DATABASE_ID: _omit, ...noProd } = ENV;
    expect(() => generate(noProd)).toThrow(/not set.*COMMONFORGE_D1_DATABASE_ID/);
    expect(() => generate({ ...ENV, COMMONFORGE_D1_DATABASE_ID: "00000000-0000-0000-0000-000000000000" })).toThrow(/COMMONFORGE_D1_DATABASE_ID must be/);
    expect(() => generate({ ...ENV, COMMONFORGE_D1_DATABASE_ID: "commonforge-dev" })).toThrow(/COMMONFORGE_D1_DATABASE_ID must be/);
    // the real production id joins the leak check
    const prodId = ENV.COMMONFORGE_D1_DATABASE_ID;
    const p = fresh();
    p.worker.d1_databases[0].database_id = prodId;
    p.worker.vars.X = `db ${prodId}`;
    expect(() => buildFromSources(p, BASE, ciNames(BASE, ENV.COMMONFORGE_CI_D1_DATABASE_ID))).toThrow(/contains production/);
    expect(() => buildFromSources(fresh(), BASE, ciNames(BASE, undefined))).toThrow(/no D1 database id/);
    expect(() => buildFromSources(fresh(), "", ciNames(BASE, ENV.COMMONFORGE_CI_D1_DATABASE_ID))).toThrow(/base/);
  });

  it("review m1: refuses unmapped keys and container names, production URLs anywhere and extra buckets", () => {
    const names = ciNames(BASE, ENV.COMMONFORGE_CI_D1_DATABASE_ID);
    const a = fresh();
    a.runner.containers[0].name = "commonforge-runner-runnerbox";
    expect(() => buildFromSources(a, BASE, names)).toThrow(/containers\[\]\.name/);
    const b = fresh();
    b.worker.vars.X = `https://commonforge-worker.${BASE}/api/`;
    expect(() => buildFromSources(b, BASE, names)).toThrow(/contains production/);
    const c = fresh();
    c.worker.r2_buckets.push({ binding: "B2", bucket_name: "other" });
    expect(() => buildFromSources(c, BASE, names)).toThrow(/R2 buckets/);
    const d = fresh();
    d.worker.kv_namespaces = [{ binding: "KV", id: "x" }];
    expect(() => buildFromSources(d, BASE, names)).toThrow(/no CI mapping for top-level key "kv_namespaces"/);
    const e = fresh();
    e.worker.routes = [{ pattern: "forge.example.org", custom_domain: true }];
    expect(() => buildFromSources(e, BASE, names)).toThrow(/no CI mapping for top-level key "routes"/);
  });

  it("derived deployments carry the admin list they are given (CI: the harness domain)", () => {
    const prodCfg = fresh();
    const names = deploymentNames("cfboot", { base: BASE, d1Id: "00000000-0000-4000-8000-000000000000" });
    expect(buildFromSources(prodCfg, BASE, names, { adminEmails: "ops@example.org" }).worker.vars.COMMONFORGE_ADMIN_EMAILS).toBe("ops@example.org");
    expect(buildFromSources(prodCfg, BASE, names, {}).worker.vars.COMMONFORGE_ADMIN_EMAILS).toBeUndefined();
    expect(ci.vars.COMMONFORGE_ADMIN_EMAILS).toBe("@commonforge.invalid");
  });

  it("Task 24: a bootstrap deployment gets its own names, its name as COMMONFORGE_DEPLOYMENT, and the email mode asked for", () => {
    const prodCfg = fresh();
    const names = deploymentNames("cfboot", { base: BASE, d1Id: "00000000-0000-4000-8000-000000000000" });
    const send = buildFromSources(prodCfg, BASE, names, { emailMode: "send", emailFrom: "login@example.org" });
    expect(send.worker.name).toBe("cfboot-worker");
    expect(send.runner.services).toEqual([{ binding: "CONTROL", service: "cfboot-worker" }]);
    expect(send.worker.vars).toMatchObject({ COMMONFORGE_DEPLOYMENT: "cfboot", COMMONFORGE_EMAIL_MODE: "send", COMMONFORGE_EMAIL_FROM: "login@example.org", COMMONFORGE_QUEUE_SUFFIX: "-cfboot", COMMONFORGE_NAMESPACE_PREFIX: "cfboot", COMMONFORGE_DEPLOY_WORKER_PREFIX: "cfboot" });
    expect(send.worker.send_email[0].allowed_sender_addresses).toEqual(["login@example.org"]);
    expect(send.worker.d1_databases[0]).toMatchObject({ database_name: "cfboot", database_id: "00000000-0000-4000-8000-000000000000" });
    expect(send.preview.r2_buckets[0].bucket_name).toBe("cfboot-assets");
    const known = [STEPS_QUEUE, OUTBOX_QUEUE, OUTBOX_DLQ, ARTIFACT_EVENTS_QUEUE].sort();
    expect(send.worker.queues.consumers.map((c: { queue: string }) => queueBaseName(c.queue, "-cfboot")).sort()).toEqual(known);
    expect(buildFromSources(prodCfg, BASE, names, { emailMode: "log" }).worker.vars.COMMONFORGE_EMAIL_MODE).toBe("log");
    expect(() => buildFromSources(prodCfg, BASE, { ...names, deployment: "production" })).toThrow(/never production/);
    // review I1: the generated CI and bootstrap configs satisfy the Worker's log-mode rule; production does not
    expect(emailLogAllowed(ci.vars as unknown as Env)).toBe(true);
    expect(emailLogAllowed(send.worker.vars as unknown as Env)).toBe(true);
    expect(emailLogAllowed({ ...prod.vars, COMMONFORGE_PUBLIC_URL: `https://commonforge-worker.${BASE}` } as unknown as Env)).toBe(false);
    expect(() => buildFromSources(prodCfg, BASE, { ...names, bucket: "commonforge-assets-dev" })).toThrow(/production resource/);
  });
});
